	output_connection_bounding_box = {
		{ -TINY_BOX_SIZE, -TINY_BOX_SIZE },
		{ TINY_BOX_SIZE, TINY_BOX_SIZE },
	},
}

---@type data.ConstantCombinatorPrototype
local constant_combinator = tlib.assign({}, base_prototype, {
	name = constants.mod_prefix .. "-constant-combinator",
	type = "constant-combinator",
})

---@type data.ArithmeticCombinatorPrototype
local arithmetic_combinator = tlib.assign({}, base_prototype, {
	name = constants.mod_prefix .. "-arithmetic-combinator",
	type = "arithmetic-combinator",
})

---@type data.DeciderCombinatorPrototype
local decider_combinator = tlib.assign({}, base_prototype, {
	name = constants.mod_prefix .. "-decider-combinator",
	type = "decider-combinator",
})

---@type data.SelectorCombinatorPrototype
local selector_combinator = tlib.assign({}, base_prototype, {
	name = constants.mod_prefix .. "-selector-combinator",
	type = "selector-combinator",
})

data:extend({
	constant_combinator,
	arithmetic_combinator,
	decider_combinator,
	selector_combinator,
})

